'use client';

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MeasuringStrategy,
  MouseSensor,
  TouchSensor,
  defaultDropAnimationSideEffects,
  useSensor,
  useSensors,
  type Announcements,
  type CollisionDetection,
  type DragEndEvent,
  type DragMoveEvent,
  type DragOverEvent,
  type DragStartEvent,
  type DropAnimation,
  type UniqueIdentifier,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { useMotionValue, useReducedMotion } from 'motion/react';
import { useCallback, useEffect, useId, useRef, useState } from 'react';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { BoardLane } from './board-lane';
import {
  detectBoardCollision,
  laneOf,
  moveAcrossLanes,
  reorderInLane,
  targetLaneOf,
} from './board-moves';
import {
  COLUMNS,
  LANES,
  TASKS,
  TASK_PREFIX,
  TEAM_NAME,
  type Columns,
  type LaneId,
  type Task,
} from './data';
import { OverlayCard } from './drag-overlay-card';

const MEASURING = { droppable: { strategy: MeasuringStrategy.Always } };

const DROP_ANIMATION: DropAnimation = {
  duration: 220,
  easing: 'cubic-bezier(0.23, 1, 0.32, 1)',
  sideEffects: defaultDropAnimationSideEffects({
    styles: { active: { opacity: '0.4' } },
  }),
};

const SCREEN_READER_INSTRUCTIONS = {
  draggable:
    'To pick up a task, press Space or Enter. Use the arrow keys to move it between lanes and cards, Space or Enter to drop it, Escape to cancel.',
};

const DEFAULT_COMPOSER_LANE: LaneId = 'todo';

function dropAnimationOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return DROP_ANIMATION;
}

function laneLabelOf(laneId: LaneId | null) {
  const lane = LANES.find((candidate) => candidate.id === laneId);
  if (lane) {
    return lane.label;
  }
  return 'the board';
}

function highestNumberOf(tasks: Record<string, Task>) {
  const numbers = Object.values(tasks).map((task) => {
    const digits = task.number.replace(/\D/g, '');
    return Number(digits);
  });
  return Math.max(0, ...numbers);
}

function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${plural}`;
}

export default function Boards01() {
  const [columns, setColumns] = useState<Columns>(COLUMNS);
  const [tasks, setTasks] = useState<Record<string, Task>>(TASKS);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [targetLaneId, setTargetLaneId] = useState<LaneId | null>(null);
  const [composerLaneId, setComposerLaneId] = useState<LaneId | null>(null);
  const [newTaskIds, setNewTaskIds] = useState<ReadonlySet<string>>(
    () => new Set()
  );
  const columnsRef = useRef(columns);
  const snapshotRef = useRef<Columns | null>(null);
  const lastOverIdRef = useRef<UniqueIdentifier | null>(null);
  const movedLaneRef = useRef(false);
  const nextNumberRef = useRef(highestNumberOf(TASKS) + 1);
  const dragX = useMotionValue(0);
  const shouldReduceMotion = useReducedMotion();
  const dndContextId = useId();
  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 4 } }),
    useSensor(TouchSensor, {
      activationConstraint: { delay: 180, tolerance: 6 },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const allTaskIds = Object.values(columns).flat();
  const trackedCount = allTaskIds.filter(
    (taskId) => tasks[taskId].isTracked
  ).length;
  const taskCountText = countLabel(allTaskIds.length, 'task', 'tasks');
  const timerText = countLabel(trackedCount, 'timer running', 'timers running');
  const metaText = `${taskCountText} · ${timerText}`;
  let activeTask: Task | null = null;
  if (activeId) {
    activeTask = tasks[activeId];
  }

  useEffect(() => {
    columnsRef.current = columns;
    const frame = requestAnimationFrame(() => {
      movedLaneRef.current = false;
    });
    return () => cancelAnimationFrame(frame);
  }, [columns]);

  const collisionDetection = useCallback<CollisionDetection>((args) => {
    const hits = detectBoardCollision(args, columnsRef.current);
    if (hits.length > 0) {
      lastOverIdRef.current = hits[0].id;
      return hits;
    }
    if (movedLaneRef.current) {
      lastOverIdRef.current = args.active.id;
    }
    const lastOverId = lastOverIdRef.current;
    if (lastOverId) {
      return [{ id: lastOverId }];
    }
    return [];
  }, []);

  const announcements: Announcements = {
    onDragStart({ active }) {
      const lane = laneOf(columnsRef.current, String(active.id));
      return `Picked up ${tasks[String(active.id)].number} in ${laneLabelOf(lane)}`;
    },
    onDragOver({ active, over }) {
      if (!over) {
        return `${tasks[String(active.id)].number} is no longer over a lane`;
      }
      const lane = targetLaneOf(columnsRef.current, String(over.id));
      return `${tasks[String(active.id)].number} is over ${laneLabelOf(lane)}`;
    },
    onDragEnd({ active }) {
      const lane = laneOf(columnsRef.current, String(active.id));
      return `${tasks[String(active.id)].number} dropped in ${laneLabelOf(lane)}`;
    },
    onDragCancel({ active }) {
      return `Moving ${tasks[String(active.id)].number} was cancelled`;
    },
  };

  function handleDragStart({ active }: DragStartEvent) {
    const taskId = String(active.id);
    snapshotRef.current = columns;
    dragX.set(0);
    setActiveId(taskId);
    setTargetLaneId(laneOf(columns, taskId));
    setComposerLaneId(null);
  }

  function handleDragMove({ delta }: DragMoveEvent) {
    dragX.set(delta.x);
  }

  function handleDragOver({ active, over }: DragOverEvent) {
    if (!over) {
      return;
    }
    const overLane = targetLaneOf(columnsRef.current, String(over.id));
    setTargetLaneId(overLane);
    const fromLane = laneOf(columnsRef.current, String(active.id));
    const isOtherLane = fromLane !== overLane;
    if (!isOtherLane) {
      return;
    }
    movedLaneRef.current = true;
    setColumns((previous) => moveAcrossLanes(previous, active, over));
  }

  function handleDragEnd({ active, over }: DragEndEvent) {
    setActiveId(null);
    setTargetLaneId(null);
    snapshotRef.current = null;
    if (!over) {
      return;
    }
    const activeTaskId = String(active.id);
    const overId = String(over.id);
    setColumns((previous) => reorderInLane(previous, activeTaskId, overId));
  }

  function handleDragCancel() {
    const snapshot = snapshotRef.current;
    if (snapshot) {
      setColumns(snapshot);
    }
    snapshotRef.current = null;
    setActiveId(null);
    setTargetLaneId(null);
  }

  const openComposer = useCallback((laneId: LaneId) => {
    setComposerLaneId(laneId);
  }, []);

  const closeComposer = useCallback(() => {
    setComposerLaneId(null);
  }, []);

  const createTask = useCallback((laneId: LaneId, title: string) => {
    const taskNumber = nextNumberRef.current;
    nextNumberRef.current = taskNumber + 1;
    const task: Task = {
      id: `task-${taskNumber}`,
      number: `${TASK_PREFIX}-${taskNumber}`,
      title,
      type: 'task',
      priority: 'medium',
      size: null,
      labels: [],
      assigneeIds: [],
      estimateMinutes: 0,
      workedMinutes: 0,
      isTracked: false,
    };
    setTasks((previous) => ({ ...previous, [task.id]: task }));
    setColumns((previous) => ({
      ...previous,
      [laneId]: [...previous[laneId], task.id],
    }));
    setNewTaskIds((previous) => new Set(previous).add(task.id));
  }, []);

  function openDefaultComposer() {
    setComposerLaneId(DEFAULT_COMPOSER_LANE);
  }

  return (
    <div className='bg-background text-foreground flex h-dvh min-h-0 w-full flex-col'>
      <div className='hairline-b border-border flex shrink-0 flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3 md:px-6'>
        <div className='flex min-w-0 items-baseline gap-2'>
          <h1 className='truncate text-lg font-semibold'>{`${TEAM_NAME} board`}</h1>
          <span className='text-muted-foreground text-xs tabular-nums'>
            {metaText}
          </span>
        </div>
        <Button onClick={openDefaultComposer} className='ml-auto'>
          <PlusIcon />
          Create task
        </Button>
      </div>
      <DndContext
        id={dndContextId}
        sensors={sensors}
        collisionDetection={collisionDetection}
        measuring={MEASURING}
        accessibility={{
          announcements,
          screenReaderInstructions: SCREEN_READER_INSTRUCTIONS,
        }}
        onDragStart={handleDragStart}
        onDragMove={handleDragMove}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
      >
        <div className='min-h-0 flex-1 overflow-x-auto overscroll-x-contain max-md:snap-x max-md:snap-proximity max-md:scroll-px-4'>
          <div className='flex h-full w-max items-start gap-3 px-4 py-3 md:px-6'>
            {LANES.map((lane) => (
              <BoardLane
                key={lane.id}
                lane={lane}
                taskIds={columns[lane.id]}
                tasks={tasks}
                newTaskIds={newTaskIds}
                isTarget={targetLaneId === lane.id}
                isComposerOpen={composerLaneId === lane.id}
                emptyLine='Drop a task here or create one'
                onOpenComposer={openComposer}
                onCloseComposer={closeComposer}
                onCreateTask={createTask}
              />
            ))}
          </div>
        </div>
        <DragOverlay dropAnimation={dropAnimationOf(shouldReduceMotion)}>
          {activeTask && <OverlayCard task={activeTask} dragX={dragX} />}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import {
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { memo, useEffect, useRef, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import {
  CARD_SURFACE,
  TRACKED_CARD,
  TaskCardBody,
  formatDuration,
} from './card-parts';
import type { LANES, LaneId, Task } from './data';

export type LaneMeta = (typeof LANES)[number];

const SORT_TRANSITION = {
  duration: 220,
  easing: 'cubic-bezier(0.23, 1, 0.32, 1)',
};

const ENTER_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const CARD_PRESENCE: Variants = {
  hidden: { height: 0, opacity: 0, overflow: 'hidden' },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ENTER_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const CARD_FADE: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1, transition: ENTER_IN },
};

function sortTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return SORT_TRANSITION;
}

function cardVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return CARD_FADE;
  }
  return CARD_PRESENCE;
}

function initialOf(isNew: boolean) {
  if (isNew) {
    return 'hidden';
  }
  return false;
}

function taskCountLabel(count: number) {
  if (count === 1) {
    return '1 task';
  }
  return `${count} tasks`;
}

function cardLabelOf(task: Task) {
  const worked = formatDuration(task.workedMinutes);
  return `${task.number} ${task.title}, ${worked} worked`;
}

function LaneCount({ value }: { value: number }) {
  const label = taskCountLabel(value);

  return (
    <span className='bg-foreground/[0.06] text-muted-foreground inline-flex h-5 min-w-5 items-center justify-center rounded-sm px-1.5 text-xs tabular-nums'>
      <span aria-hidden='true' className='inline-flex'>
        <MotionNumber value={value} />
      </span>
      <span className='sr-only'>{` ${label}`}</span>
    </span>
  );
}

export function LaneTile({ lane }: { lane: LaneMeta }) {
  const LaneGlyph = lane.icon;
  const tileStyle = { '--chip': lane.color } as React.CSSProperties;

  return (
    <span
      style={tileStyle}
      className='chip-3d flex size-5 shrink-0 items-center justify-center rounded-md'
    >
      <LaneGlyph className='size-3' strokeWidth={2.25} />
    </span>
  );
}

function SortableTaskCard({ task, isNew }: { task: Task; isNew: boolean }) {
  const shouldReduceMotion = useReducedMotion();
  const cardVariants = cardVariantsOf(shouldReduceMotion);
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: task.id,
    transition: sortTransitionOf(shouldReduceMotion),
  });
  const style = {
    transform: CSS.Translate.toString(transform),
    transition,
  } as React.CSSProperties;

  return (
    <motion.li
      variants={cardVariants}
      initial={initialOf(isNew)}
      animate='shown'
    >
      <div
        ref={setNodeRef}
        style={style}
        {...attributes}
        {...listeners}
        aria-label={cardLabelOf(task)}
        className={cn(
          CARD_SURFACE,
          task.isTracked && TRACKED_CARD,
          'focus-visible:ring-ring/25 cursor-grab touch-manipulation outline-none focus-visible:ring-[3px] active:cursor-grabbing',
          '[contain-intrinsic-size:auto_9rem] [content-visibility:auto]',
          isDragging && 'opacity-40'
        )}
      >
        <TaskCardBody task={task} />
      </div>
    </motion.li>
  );
}

function LaneComposer({
  laneLabel,
  onCreate,
  onClose,
}: {
  laneLabel: string;
  onCreate: (title: string) => void;
  onClose: () => void;
}) {
  const [title, setTitle] = useState('');
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    formRef.current?.scrollIntoView({ block: 'nearest' });
  }, []);

  function changeTitle(event: React.ChangeEvent<HTMLInputElement>) {
    setTitle(event.target.value);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      onClose();
    }
  }

  function create(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmed = title.trim();
    if (trimmed.length === 0) {
      return;
    }
    onCreate(trimmed);
    setTitle('');
  }

  return (
    <form
      ref={formRef}
      onSubmit={create}
      className={cn(CARD_SURFACE, 'flex flex-col gap-2 p-2')}
    >
      <Input
        autoFocus
        value={title}
        placeholder='Task title'
        aria-label={`Title of the new task in ${laneLabel}`}
        onChange={changeTitle}
        onKeyDown={handleKeyDown}
      />
      <div className='flex items-center justify-end gap-1'>
        <Button type='button' variant='ghost' size='sm' onClick={onClose}>
          Cancel
        </Button>
        <Button type='submit' size='sm'>
          Add task
        </Button>
      </div>
    </form>
  );
}

type BoardLaneProps = {
  lane: LaneMeta;
  taskIds: string[];
  tasks: Record<string, Task>;
  newTaskIds: ReadonlySet<string>;
  isTarget: boolean;
  isComposerOpen: boolean;
  emptyLine: string;
  menu?: React.ReactNode;
  onOpenComposer: (laneId: LaneId) => void;
  onCloseComposer: () => void;
  onCreateTask: (laneId: LaneId, title: string) => void;
};

/** A tinted lane whose body scrolls on its own. It takes drops anywhere, even when empty. */
export const BoardLane = memo(function BoardLane({
  lane,
  taskIds,
  tasks,
  newTaskIds,
  isTarget,
  isComposerOpen,
  emptyLine,
  menu,
  onOpenComposer,
  onCloseComposer,
  onCreateTask,
}: BoardLaneProps) {
  const { setNodeRef } = useDroppable({ id: lane.id });
  const isEmpty = taskIds.length === 0;

  function openComposer() {
    onOpenComposer(lane.id);
  }

  function createTask(title: string) {
    onCreateTask(lane.id, title);
  }

  return (
    <section
      ref={setNodeRef}
      aria-label={lane.label}
      className={cn(
        'flex max-h-full w-72 shrink-0 snap-start flex-col rounded-xl transition-colors duration-150',
        isTarget && 'bg-primary/[0.06]',
        !isTarget && 'bg-foreground/[0.03]'
      )}
    >
      <header className='flex h-11 shrink-0 items-center gap-2 pr-1.5 pl-3'>
        <LaneTile lane={lane} />
        <h2 className='min-w-0 truncate text-[13px] font-semibold'>
          {lane.label}
        </h2>
        <LaneCount value={taskIds.length} />
        <div className='ml-auto flex items-center'>
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label={`Add a task to ${lane.label}`}
            onClick={openComposer}
            className='text-muted-foreground'
          >
            <PlusIcon />
          </Button>
          {menu}
        </div>
      </header>
      <div className='flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto px-2 pt-0.5 pb-2'>
        <SortableContext items={taskIds} strategy={verticalListSortingStrategy}>
          <ul className='flex flex-col gap-2'>
            {taskIds.map((taskId) => (
              <SortableTaskCard
                key={taskId}
                task={tasks[taskId]}
                isNew={newTaskIds.has(taskId)}
              />
            ))}
          </ul>
        </SortableContext>
        {isEmpty && (
          <div
            className={cn(
              'hairline-border text-muted-foreground flex h-20 items-center justify-center rounded-lg border-dashed px-3 text-center text-xs transition-colors duration-150',
              isTarget && 'border-primary/40',
              !isTarget && 'border-foreground/20'
            )}
          >
            {emptyLine}
          </div>
        )}
        {isComposerOpen && (
          <LaneComposer
            laneLabel={lane.label}
            onCreate={createTask}
            onClose={onCloseComposer}
          />
        )}
        {!isComposerOpen && (
          <button
            type='button'
            onClick={openComposer}
            className='text-muted-foreground hover:bg-foreground/5 hover:text-foreground focus-visible:ring-ring/25 flex h-8 w-full shrink-0 cursor-pointer items-center gap-2 rounded-md px-2 text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]'
          >
            <PlusIcon className='size-4' />
            Create task
          </button>
        )}
      </div>
    </section>
  );
});

import { memo } from 'react';

import { ClockIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';

import {
  ISSUE_TYPES,
  LABELS,
  PEOPLE,
  PRIORITIES,
  type IssueType,
  type Person,
  type Task,
} from './data';

const VISIBLE_LABELS = 2;

const VISIBLE_ASSIGNEES = 3;

const NEUTRAL_CHIP = 'var(--muted-foreground)';

export const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-lg shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

export const TRACKED_CARD = 'ring-primary/45';

export function formatDuration(minutes: number) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const paddedRest = String(rest).padStart(2, '0');
  return `${hours}h ${paddedRest}m`;
}

function personOf(personId: string): Person | undefined {
  return PEOPLE.find((person) => person.id === personId);
}

function isPerson(value: Person | undefined): value is Person {
  return value !== undefined;
}

function progressOf(task: Task) {
  if (task.estimateMinutes === 0) {
    return 0;
  }
  const ratio = task.workedMinutes / task.estimateMinutes;
  return Math.min(100, Math.round(ratio * 100));
}

export function IssueTypeGem({ type }: { type: IssueType }) {
  const meta = ISSUE_TYPES[type];
  const TypeGlyph = meta.icon;
  const gemStyle = { '--gem': meta.color } as React.CSSProperties;

  return (
    <span
      style={gemStyle}
      className='gem-plate inline-flex size-4 shrink-0 items-center justify-center rounded-[4px]'
    >
      <TypeGlyph className='size-2.5' strokeWidth={2.75} />
      <span className='sr-only'>{meta.label}</span>
    </span>
  );
}

function AssigneeStack({ assigneeIds }: { assigneeIds: string[] }) {
  const people = assigneeIds.map(personOf).filter(isPerson);
  const shown = people.slice(0, VISIBLE_ASSIGNEES);
  const hiddenCount = people.length - shown.length;
  const hasHidden = hiddenCount > 0;
  const isUnassigned = people.length === 0;

  if (isUnassigned) {
    return <span className='text-muted-foreground text-xs'>Unassigned</span>;
  }

  return (
    <span className='flex items-center'>
      {shown.map((person) => (
        <Avatar
          key={person.id}
          className='ring-card -ml-1 size-5 text-[9px] ring-2 first:ml-0'
        >
          {person.avatar && <AvatarImage src={person.avatar} alt='' />}
          <AvatarFallback>{person.initials}</AvatarFallback>
        </Avatar>
      ))}
      {hasHidden && (
        <span className='bg-muted text-muted-foreground ring-card -ml-1 inline-flex size-5 items-center justify-center rounded-full text-[9px] font-medium ring-2'>
          +{hiddenCount}
        </span>
      )}
      <span className='sr-only'>
        {`Assigned to ${people.map((person) => person.name).join(', ')}`}
      </span>
    </span>
  );
}

type TaskCardBodyProps = {
  task: Task;
};

/** The content of a card. Memoised, so a drag re-renders only the thin sortable wrapper around it. */
export const TaskCardBody = memo(function TaskCardBody({
  task,
}: TaskCardBodyProps) {
  const priority = PRIORITIES[task.priority];
  const shownLabels = task.labels.slice(0, VISIBLE_LABELS);
  const hiddenLabelCount = task.labels.length - shownLabels.length;
  const hasHiddenLabels = hiddenLabelCount > 0;
  const hasEstimate = task.estimateMinutes > 0;
  const progress = progressOf(task);
  const progressStyle = { width: `${progress}%` } as React.CSSProperties;

  return (
    <div className='flex flex-col gap-2.5 p-3'>
      <div className='flex flex-wrap items-center gap-1'>
        <Chip color={priority.color}>{priority.label}</Chip>
        {task.size && <Chip color={NEUTRAL_CHIP}>{`Size ${task.size}`}</Chip>}
        {shownLabels.map((labelId) => {
          const label = LABELS[labelId];
          return (
            <Chip key={labelId} color={label.color}>
              {label.label}
            </Chip>
          );
        })}
        {hasHiddenLabels && (
          <Chip color={NEUTRAL_CHIP}>{`+${hiddenLabelCount}`}</Chip>
        )}
      </div>
      <div className='flex flex-col gap-1'>
        <span className='text-muted-foreground flex items-center gap-1.5 text-xs tabular-nums'>
          <IssueTypeGem type={task.type} />
          {task.number}
        </span>
